const util = require('../../util');

function like(reStr, flags) {
  // Without flags the second argument is ruleBuilders. Arguments after the flags are ignored
  const isIgnoreCase = typeof flags === 'string' && flags.indexOf('i') !== -1;
  const re = new RegExp(reStr, isIgnoreCase ? 'i' : '');

  return (value, params, outputArr) => {
    if (util.isNoValue(value)) return;

    if (!util.isPrimitiveValue(value)) return 'FORMAT_ERROR';

    value += '';
    if (!re.test(value)) return 'WRONG_FORMAT';
    outputArr.push(value);
  };
}

module.exports = like;
